import java.util.*;

class Solution {
    public int findMaxConsecutiveOnes(int[] lamps) {
        int cur = 0, best = 0;
        for (int x : lamps) {
            cur = (x == 1) ? cur + 1 : 0;  // extend or reset the current streak
            best = Math.max(best, cur);
        }
        return best;
    }
}

